ALTER TABLE addresses ADD COLUMN region_code varchar(80);ALTER TABLE material_consumption_runs ADD COLUMN evaluated_parameters jsonb CHECK(evaluated_parameters IS NULL OR jsonb_typeof(evaluated_parameters)='object'),ADD COLUMN work_quantity numeric(20,8)CHECK(work_quantity IS NULL OR work_quantity>0),ADD COLUMN work_quantity_unit varchar(40);
CREATE TABLE regional_pricing_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,code varchar(80) NOT NULL,title varchar(300) NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE regional_pricing_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,profile_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','ready_for_approval','approved','superseded','cancelled')),is_current boolean NOT NULL DEFAULT true,country_code char(2) NOT NULL CHECK(country_code~'^[A-Z]{2}$'),region_code varchar(80) NOT NULL,city varchar(160),customer_category varchar(120) NOT NULL,commercial_profile varchar(120) NOT NULL,currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),effective_from date NOT NULL,effective_to date,price_source varchar(500) NOT NULL,overhead_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(overhead_rules)='array'),tax_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(tax_rules)='array'),margin_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(margin_rules)='array'),discount_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(discount_rules)='array'),adjustment_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(adjustment_rules)='array'),calculation_version varchar(80) NOT NULL,version bigint NOT NULL DEFAULT 1,approved_at timestamptz,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,profile_id,revision_number),FOREIGN KEY(tenant_id,profile_id)REFERENCES regional_pricing_profiles(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK(effective_to IS NULL OR effective_to>=effective_from),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE UNIQUE INDEX uq_regional_pricing_current ON regional_pricing_revisions(tenant_id,profile_id)WHERE is_current;
CREATE TABLE regional_price_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,revision_id uuid NOT NULL,price_kind text NOT NULL CHECK(price_kind IN('labor','material','equipment','subcontractor','transport','disposal')),reference_code varchar(160) NOT NULL,description varchar(500) NOT NULL,rate_type varchar(80) NOT NULL,unit_code varchar(40) NOT NULL,unit_price numeric(20,6) NOT NULL CHECK(unit_price>=0),price_variant text NOT NULL CHECK(price_variant IN('current_purchase','reference','average','contract','rental','ownership','hourly','daily','unit','crew','fixed')),minimum_order numeric(20,8)CHECK(minimum_order>=0),package_price numeric(20,6)CHECK(package_price>=0),pallet_price numeric(20,6)CHECK(pallet_price>=0),valid_from date NOT NULL,valid_to date,source_reference varchar(500) NOT NULL,metadata jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(metadata)='object'),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,price_kind,reference_code,rate_type),FOREIGN KEY(tenant_id,revision_id)REFERENCES regional_pricing_revisions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE approved_regional_pricing_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,profile_id uuid NOT NULL,revision_id uuid NOT NULL,revision_number integer NOT NULL,content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'AND pg_column_size(content)<=4194304),content_fingerprint char(64) NOT NULL,schema_version varchar(40) NOT NULL DEFAULT'regional-pricing-v1',approved_at timestamptz NOT NULL DEFAULT now(),approved_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id),FOREIGN KEY(tenant_id,profile_id)REFERENCES regional_pricing_profiles(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES regional_pricing_revisions(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id));
CREATE TABLE commercial_estimates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,code varchar(80) NOT NULL,title varchar(300) NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE commercial_estimate_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','ready_for_approval','approved','superseded','cancelled')),is_current boolean NOT NULL DEFAULT true,mode text NOT NULL CHECK(mode IN('budget','preliminary','tender','approved_client','internal_cost')),material_consumption_snapshot_id uuid NOT NULL,pricing_snapshot_id uuid NOT NULL,currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),customer_category varchar(120) NOT NULL,commercial_profile varchar(120) NOT NULL,manual_margin_percent numeric(9,4)CHECK(manual_margin_percent>=0 AND manual_margin_percent<100),manual_discount_percent numeric(9,4)CHECK(manual_discount_percent BETWEEN 0 AND 100),override_reason varchar(2000),totals jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(totals)='object'),calculation_version varchar(80) NOT NULL,version bigint NOT NULL DEFAULT 1,approved_at timestamptz,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,estimate_id,revision_number),FOREIGN KEY(tenant_id,estimate_id)REFERENCES commercial_estimates(tenant_id,id),FOREIGN KEY(tenant_id,material_consumption_snapshot_id)REFERENCES approved_material_consumption_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,pricing_snapshot_id)REFERENCES approved_regional_pricing_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((manual_margin_percent IS NULL AND manual_discount_percent IS NULL)OR override_reason IS NOT NULL),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE UNIQUE INDEX uq_commercial_estimate_current ON commercial_estimate_revisions(tenant_id,estimate_id)WHERE is_current;
CREATE TABLE commercial_estimate_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,revision_id uuid NOT NULL,work_code varchar(120) NOT NULL,localized_description varchar(1000) NOT NULL,target_element varchar(300) NOT NULL,quantity numeric(20,8) NOT NULL CHECK(quantity>0),unit_code varchar(40) NOT NULL,labor_cost numeric(20,4) NOT NULL CHECK(labor_cost>=0),material_cost numeric(20,4) NOT NULL CHECK(material_cost>=0),equipment_cost numeric(20,4) NOT NULL CHECK(equipment_cost>=0),other_cost numeric(20,4) NOT NULL CHECK(other_cost>=0),overhead numeric(20,4) NOT NULL CHECK(overhead>=0),internal_cost numeric(20,4) NOT NULL CHECK(internal_cost>=0),unit_price numeric(20,4) NOT NULL CHECK(unit_price>=0),net_total numeric(20,4) NOT NULL CHECK(net_total>=0),discount_amount numeric(20,4) NOT NULL CHECK(discount_amount>=0),vat_amount numeric(20,4) NOT NULL CHECK(vat_amount>=0),gross_total numeric(20,4) NOT NULL CHECK(gross_total>=0),profit numeric(20,4) NOT NULL,margin_percent numeric(9,4) NOT NULL,currency char(3) NOT NULL,price_source varchar(500) NOT NULL,calculation_trace jsonb NOT NULL CHECK(jsonb_typeof(calculation_trace)='object'),engineering_references jsonb NOT NULL CHECK(jsonb_typeof(engineering_references)='object'),norm_revision_number integer NOT NULL,technology_version_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id,work_code),FOREIGN KEY(tenant_id,estimate_id)REFERENCES commercial_estimates(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES commercial_estimate_revisions(tenant_id,id),FOREIGN KEY(tenant_id,technology_version_id)REFERENCES execution_technology_versions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id));
CREATE TABLE approved_commercial_estimate_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,revision_id uuid NOT NULL,revision_number integer NOT NULL,project_id uuid NOT NULL,content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'AND pg_column_size(content)<=4194304),content_fingerprint char(64) NOT NULL,schema_version varchar(40) NOT NULL DEFAULT'commercial-estimate-v1',approved_at timestamptz NOT NULL DEFAULT now(),approved_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id),FOREIGN KEY(tenant_id,estimate_id)REFERENCES commercial_estimates(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES commercial_estimate_revisions(tenant_id,id),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id));
CREATE FUNCTION protect_approved_regional_pricing_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'APPROVED_REGIONAL_PRICING_SNAPSHOT_IMMUTABLE';END$$;CREATE TRIGGER immutable_approved_regional_pricing_snapshot BEFORE UPDATE OR DELETE ON approved_regional_pricing_snapshots FOR EACH ROW EXECUTE FUNCTION protect_approved_regional_pricing_snapshot();CREATE FUNCTION protect_approved_commercial_estimate_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'APPROVED_COMMERCIAL_ESTIMATE_SNAPSHOT_IMMUTABLE';END$$;CREATE TRIGGER immutable_approved_commercial_estimate_snapshot BEFORE UPDATE OR DELETE ON approved_commercial_estimate_snapshots FOR EACH ROW EXECUTE FUNCTION protect_approved_commercial_estimate_snapshot();
CREATE FUNCTION protect_approved_regional_pricing_content()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE state text;BEGIN SELECT status INTO state FROM regional_pricing_revisions WHERE id=CASE WHEN TG_OP='DELETE'THEN OLD.revision_id ELSE NEW.revision_id END;IF state IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_REGIONAL_PRICING_IMMUTABLE';END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END$$;CREATE TRIGGER immutable_regional_price_entries BEFORE INSERT OR UPDATE OR DELETE ON regional_price_entries FOR EACH ROW EXECUTE FUNCTION protect_approved_regional_pricing_content();
CREATE FUNCTION protect_approved_commercial_estimate_content()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE state text;BEGIN SELECT status INTO state FROM commercial_estimate_revisions WHERE id=CASE WHEN TG_OP='DELETE'THEN OLD.revision_id ELSE NEW.revision_id END;IF state IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_COMMERCIAL_ESTIMATE_IMMUTABLE';END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END$$;CREATE TRIGGER immutable_commercial_estimate_lines BEFORE INSERT OR UPDATE OR DELETE ON commercial_estimate_lines FOR EACH ROW EXECUTE FUNCTION protect_approved_commercial_estimate_content();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['regional_pricing_profiles','regional_pricing_revisions','regional_price_entries','approved_regional_pricing_snapshots','commercial_estimates','commercial_estimate_revisions','commercial_estimate_lines','approved_commercial_estimate_snapshots']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_%I ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
CREATE INDEX idx_regional_pricing_match ON regional_pricing_revisions(tenant_id,country_code,region_code,city,currency,effective_from,effective_to);CREATE INDEX idx_regional_entries ON regional_price_entries(tenant_id,revision_id,price_kind,reference_code);CREATE INDEX idx_commercial_estimates_project ON commercial_estimates(tenant_id,project_id,updated_at DESC);CREATE INDEX idx_commercial_estimate_lines ON commercial_estimate_lines(tenant_id,revision_id);
INSERT INTO permissions(code,description)VALUES('regional_pricing.create','Create regional pricing'),('regional_pricing.read','Read regional pricing'),('regional_pricing.edit','Edit draft regional pricing'),('regional_pricing.review','Review regional pricing'),('regional_pricing.approve','Approve regional pricing'),('regional_pricing.snapshots.read','Read pricing snapshots'),('commercial_estimates.create','Create commercial estimates'),('commercial_estimates.read','Read commercial estimates'),('commercial_estimates.review','Review commercial estimates'),('commercial_estimates.approve','Approve commercial estimates'),('commercial_estimates.snapshots.read','Read estimate snapshots')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE(r.code IN('tenant_admin','project_manager','finance_manager')AND(p.code LIKE'regional_pricing.%'OR p.code LIKE'commercial_estimates.%'))OR(r.code='employee'AND p.code IN('regional_pricing.read','commercial_estimates.read'))OR(r.code='read_only'AND p.code IN('regional_pricing.read','regional_pricing.snapshots.read','commercial_estimates.read','commercial_estimates.snapshots.read'))ON CONFLICT DO NOTHING;
